import pandas as pd
df = pd.read_csv('${item}')
issues = ${issues_report}
for col, count in issues['missing'].items():
    if count > 0:
        if df[col].dtype in ['int64','float64']:
            df[col].fillna(df[col].median(), inplace=True)
        else:
            df[col].fillna(df[col].mode()[0], inplace=True)
df.drop_duplicates(inplace=True)
for col, count in issues['outliers'].items():
    if count > 0:
        Q1 = df[col].quantile(0.25)
        Q3 = df[col].quantile(0.75)
        IQR = Q3 - Q1
        lower = Q1 - 1.5 * IQR
        upper = Q3 + 1.5 * IQR
        df[col] = df[col].clip(lower, upper)
env['cleaned_df'] = df

pkg = {}
pkg['file'] = '${item}'
pkg['schema'] = ${schema_report}
pkg['issues'] = ${issues_report}
pkg['validation'] = ${validation_report}
pkg['stats'] = ${per_file_stats}
env['file_package'] = pkg

all_packages = ${all_packages}
merged = {}
merged['files'] = [pkg['file'] for pkg in all_packages]
merged['total_rows'] = sum(pkg['stats']['count'] for pkg in all_packages)
first_stats = all_packages[0]['stats']
numeric_cols = list(first_stats['sum'].keys())
merged['total_sum'] = {col: sum(pkg['stats']['sum'][col] for pkg in all_packages) for col in numeric_cols}
merged['overall_mean'] = {col: merged['total_sum'][col] / merged['total_rows'] for col in numeric_cols}
env['merged_stats'] = merged

all_packages = ${all_packages}
merged = ${merged_stats}
review = {}
review['files_processed'] = len(merged['files'])
review['total_rows'] = merged['total_rows']
review['total_issues'] = {}
for pkg in all_packages:
    file = pkg['file']
    review['total_issues'][file] = {
        'missing_before': sum(pkg['issues']['missing'].values()),
        'duplicates_before': pkg['issues']['duplicates'],
        'outliers_before': sum(pkg['issues']['outliers'].values()),
        'missing_after': pkg['validation']['missing_after'],
        'duplicates_after': pkg['validation']['duplicates_after']
    }
review['summary'] = 'All files repaired and revalidated successfully.'
env['review_report'] = review

