          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\ndf = pd.read_csv('${item}')\nissues = {}\nissues['columns'] = list(df.columns)\nissues['missing'] = df.isnull().sum().to_dict()\nissues['duplicates'] = df.duplicated().sum()\nnumeric_cols = df.select_dtypes(include='number').columns\noutliers = {}\nfor col in numeric_cols:\n    Q1 = df[col].quantile(0.25)\n    Q3 = df[col].quantile(0.75)\n    IQR = Q3 - Q1\n    outliers[col] = int(((df[col] < (Q1 - 1.5 * IQR)) | (df[col] > (Q3 + 1.5 * IQR))).sum())\nissues['outliers'] = outliers\nenv['issues_report'] = issues",
          "output": {
            "name": "issues_report",
            "typeName": "Record",
            "fields": [
              {"name": "columns", "typeName": "List<String>"},
              {"name": "missing", "typeName": "Record"},
              {"name": "duplicates", "typeName": "Integer"},
              {"name": "outliers", "typeName": "Record"}
            ]
          }
