        {
          "name": "repair",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\ndf = pd.read_csv('${item}')\nissues = ${issues_report}\nfor col, count in issues['missing'].items():\n    if count > 0:\n        if df[col].dtype in ['int64','float64']:\n            df[col].fillna(df[col].median(), inplace=True)\n        else:\n            df[col].fillna(df[col].mode()[0], inplace=True)\ndf.drop_duplicates(inplace=True)\nfor col, count in issues['outliers'].items():\n    if count > 0:\n        Q1 = df[col].quantile(0.25)\n        Q3 = df[col].quantile(0.75)\n        IQR = Q3 - Q1\n        lower = Q1 - 1.5 * IQR\n        upper = Q3 + 1.5 * IQR\n        df[col] = df[col].clip(lower, upper)\nenv['cleaned_df'] = df",
          "inputBindings": [
            {"param": "issues_report", "source": "detect_issues", "binding": "issues_report"}
          ],
          "output": {
            "name": "cleaned_df",
            "typeName": "Any"
          }
        },
        {
          "name": "revalidate",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "df = ${cleaned_df}\nvalidation = {}\nvalidation['missing_after'] = int(df.isnull().sum().sum())\nvalidation['duplicates_after'] = int(df.duplicated().sum())\nvalidation['row_count'] = len(df)\nvalidation['columns'] = list(df.columns)\nenv['validation_report'] = validation",
          "inputBindings": [
            {"param": "cleaned_df", "source": "repair", "binding": "cleaned_df"}
