          "name": "compute_stats",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "df = ${cleaned_df}\nstats = {}\nnumeric_cols = df.select_dtypes(include='number').columns\nstats['sum'] = df[numeric_cols].sum().to_dict()\nstats['mean'] = df[numeric_cols].mean().to_dict()\nstats['count'] = len(df)\nstats['file'] = '${item}'\nenv['per_file_stats'] = stats",
