      "kind": "primitive",
      "capability": "execute_python",
      "code": "all_packages = ${all_packages}\nmerged = ${merged_stats}\nreview = {}\nreview['files_processed'] = len(merged['files'])\nreview['total_rows'] = merged['total_rows']\nreview['total_issues'] = {}\nfor pkg in all_packages:\n    file = pkg['file']\n    review['total_issues'][file] = {\n        'missing_before': sum(pkg['issues']['missing'].values()),\n        'duplicates_before': pkg['issues']['duplicates'],\n        'outliers_before': sum(pkg['issues']['outliers'].values()),\n        'missing_after': pkg['validation']['missing_after'],\n        'duplicates_after': pkg['validation']['duplicates_after']\n    }\nreview['summary'] = 'All files repaired and revalidated successfully.'\nenv['review_report'] = review",
