          {"name": "total_rows", "typeName": "Integer"},
          {"name": "total_issues", "typeName": "Record"},
          {"name": "summary", "typeName": "String"}
        ]
      }
    },
    {
      "name": "generate_report",
      "kind": "primitive",
      "capability": "execute_python",
      "code": "all_packages = ${all_packages}\nmerged = ${merged_stats}\nreview = ${review_report}\nreport_lines = []\nreport_lines.append('# Consolidated Quarterly Sales Report')\nreport_lines.append('')\nreport_lines.append('## Evidence Log')\nreport_lines.append('')\nfor pkg in all_packages:\n    file = pkg['file']\n    report_lines.append(f'### File: {file}')\n    report_lines.append(f'- Schema: {len(pkg[\"schema\"][\"columns\"])} columns, {pkg[\"schema\"][\"row_count\"]} rows')\n    report_lines.append(f'- Issues detected: {sum(pkg[\"issues\"][\"missing\"].values())} missing, {pkg[\"issues\"][\"duplicates\"]} duplicates, {sum(pkg[\"issues\"][\"outliers\"].values())} outliers')\n    report_lines.append(f'- Validation after repair: {pkg[\"validation\"][\"missing_after\"]} missing, {pkg[\"validation\"][\"duplicates_after\"]} duplicates, {pkg[\"validation\"][\"row_count\"]} rows')\n    report_lines.append(f'- Quarterly stats: sum={pkg[\"stats\"][\"sum\"]}, mean={pkg[\"stats\"][\"mean\"]}')\n    report_lines.append('')\nreport_lines.append('## Merged Results')\nreport_lines.append(f'- Total rows across all files: {merged[\"total_rows\"]}')\nreport_lines.append(f'- Total sums: {merged[\"total_sum\"]}')\nreport_lines.append(f'- Overall means: {merged[\"overall_mean\"]}')\nreport_lines.append('')\nreport_lines.append('## Quality Review')\nreport_lines.append(f'- Files processed: {review[\"files_processed\"]}')\nreport_lines.append(f'- Issues per file: {review[\"total_issues\"]}')\nreport_lines.append(f'- Summary: {review[\"summary\"]}')\nreport = '\\n'.join(report_lines)\nenv['final_report'] = {'content': report}",
